/** Full Lab Report with NABL compliance */
export interface LabReportFullPrintData {
  patient_name: string;
  uhid: string;
  age_display: string;
  gender: string;
  sample_id: string;
  accession_number: string;
  order_date: string;
  collection_date: string | null;
  report_date: string;
  referring_doctor: string | null;
  department: string | null;
  ward_name: string | null;
  bed_number: string | null;
  test_name: string;
  test_code: string | null;
  loinc_code: string | null;
  specimen_type: string | null;
  /**
   * preliminary / final / amended. An amended report that looks exactly
   * like the one it replaces is a clinician acting on a withdrawn value.
   */
  report_status: string | null;
  parameters: LabParameter[];
  interpretation: string | null;
  comments: string | null;
  pathologist_name: string;
  pathologist_registration_number: string | null;
  pathologist_signature_url: string | null;
  technician_name: string | null;
  verified_at: string | null;
  nabl_accredited: boolean;
  nabl_certificate_number: string | null;
  nabl_logo_url: string | null;
  barcode_data: string;
  hospital_name: string;
  hospital_logo_url: string | null;
  /** Pathologist + co-signer signatures stamped onto the PDF. */
  signatures: PrintSignatureData[];
  /**
   * What this report corrected, if anything.
   *
   * An amendment overwrites the value in place. A corrected report that
   * does not say what it corrected is not a corrected report — the copy in
   * somebody's hand still shows the old number, and nothing on the new one
   * tells them which line to look at.
   */
  amendments: PrintAmendment[];
}

export interface PrintAmendment {
  parameter_name: string;
  original_value: string | null;
  amended_value: string | null;
  original_flag: string | null;
  amended_flag: string | null;
  reason: string;
  amended_at: string;
  amended_by_name: string | null;
}

export interface LabParameter {
  parameter_name: string;
  result_value: string;
  unit: string | null;
  reference_range: string | null;
  is_abnormal: boolean;
  is_critical: boolean;
  critical_flag: string | null;
  method: string | null;
  /**
   * The same analyte's last value, and how far this one has moved from it.
   * Computed and stored at entry, shown on the order screen, and until now
   * missing from the printed report -- so a clinician holding the PDF
   * could not see that a creatinine had doubled since yesterday.
   */
  previous_value: string | null;
  delta_percent: string | null;
  is_delta_flagged: boolean;
  /**
   * Blood / Serum / Urine, per row. A report covering several
   * investigations draws from more than one specimen, and the
   * phlebotomist's tube is not obvious from the analyte name.
   */
  sample_type: string | null;
  /**
   * The discipline heading this row files under -- Biochemistry,
   * Haematology. Printed reports group by it rather than listing
   * thirty analytes flat.
   */
  section: string | null;
}

