/**
 * The label that goes on the box a patient carries home.
 *
 * Not a receipt: a receipt says what was paid for, a label says what to take
 * and when. It is the only part of a dispense the patient still has at
 * 2am, so it carries the directions, the batch and expiry that make a recall
 * possible, and the schedule warning the Drugs and Cosmetics Act requires on
 * a prescription-only medicine.
 */
export interface DispensingLabelPrintData {
  hospital_name: string;
  patient_name: string;
  uhid: string;
  /**
   * Age and sex, printed together the way a label prints them — a second
   * identifier beside the name, per IPSG-1.
   */
  patient_age_sex: string | null;
  drug_name: string;
  generic_name: string | null;
  strength: string | null;
  dosage_form: string | null;
  quantity_dispensed: string;
  /**
   * "1 tablet twice daily after food" — assembled from the prescription,
   * blank when the dispense has no prescription behind it.
   */
  directions: string | null;
  route: string | null;
  duration: string | null;
  batch_number: string | null;
  expiry_date: string | null;
  storage_conditions: string | null;
  /**
   * "Schedule H — to be sold by retail on the prescription of a registered
   * medical practitioner only", and the rest of the D&C Act wording.
   */
  schedule_warning: string | null;
  black_box_warning: string | null;
  is_controlled: boolean | null;
  dispensed_on: string;
  dispensed_by: string | null;
  prescriber_name: string | null;
}

export interface GstInvoicePrintData {
  invoice_number: string;
  patient_name: string;
  uhid: string;
  subtotal: string;
  tax_amount: string;
  total_amount: string;
  hospital_gstin: string | null;
  hospital_name: string | null;
  hospital_address: string | null;
  items: GstInvoiceItemLine[];
  date: string;
  /** Any line is a medicine: print it as a pharmacy bill. */
  is_pharmacy: boolean;
  patient_phone: string | null;
  /** Shown when a Schedule H1 or X drug is on the bill. */
  patient_address: string | null;
  prescriber_name: string | null;
  prescriber_registration: string | null;
  pharmacist_name: string | null;
  pharmacist_registration: string | null;
  /** The pharmacy's drug licence numbers (Form 20/21), as the hospital set them. */
  drug_licence: string | null;
  cgst_total: string;
  sgst_total: string;
  /** Sum of MRP × quantity over medicine lines; none without MRPs. */
  mrp_total: string | null;
  /** MRP total less what was billed, when positive. */
  savings: string | null;
  paid_amount: string;
  balance_due: string;
  /** The prescription's last valid day and refills left, for a dispensed Rx. */
  rx_valid_until: string | null;
  refills_left: number | null;
  /** Schedules on the bill (e.g. "H", "H1", "X"), for their printed warnings. */
  schedules: string[];
  /** `upi://pay` link for the balance, when the hospital has a UPI ID. */
  upi_link: string | null;
  /** Public page that confirms this bill is genuine. */
  verify_url: string | null;
}

export interface GstInvoiceItemLine {
  description: string;
  hsn_code: string | null;
  quantity: number;
  unit_price: string;
  tax_percent: string;
  total_price: string;
  generic_name: string | null;
  schedule: string | null;
  manufacturer: string | null;
  batch_number: string | null;
  /** "MM/YY", as packs print it. */
  expiry: string | null;
  mrp: string | null;
  discount_amount: string;
  cgst_amount: string;
  sgst_amount: string;
}
